$('#worldForm').onsubmit=e=>{e.preventDefault();const seed=$('#worldSeed').value.trim();if(!seed){$('#worldSeed').setCustomValidity('Enter a world seed.');$('#worldSeed').reportValidity();return}visitSeed(seed)};
$('#worldSeed').oninput=e=>e.target.setCustomValidity('');$('#newWorld').onclick=()=>visitSeed(newSeed());
const clock=new THREE.Clock();function animate(){requestAnimationFrame(animate);let dt=Math.min(clock.getDelta(),.05);elapsed+=dt;water.material.uniforms.time.value+=dt*.32;if(playing&&!paused){const forward=(keys.w||keys.arrowup||keys.auto?1:0)-(keys.s||keys.arrowdown?1:0);const turn=(keys.a||keys.arrowleft?1:0)-(keys.d||keys.arrowright?1:0);yaw+=turn*dt*.68;speed=THREE.MathUtils.damp(speed,forward*4.3,forward?1.5:.65,dt);let nx=position.x-Math.sin(yaw)*speed*dt,nz=position.z-Math.cos(yaw)*speed*dt;let allowed=isWater(world,nx,nz,.65);if(allowed){position.x=nx;position.z=nz}else speed=-speed*.2;$('#place').textContent='The open water';places.forEach((p,i)=>{if(Math.hypot(position.x-p.x,position.z-p.z)<p.r){$('#place').textContent=p.name;if(!found.has(i)){found.add(i);$('#found').textContent=found.size;$('#progress').style.width=found.size/places.length*100+'%';toast('<small>A QUIET PLACE DISCOVERED</small><br>'+p.name+'<br><small>'+p.note+'</small>')}}});if(elapsed-lastRipple>.48&&Math.abs(speed)>.25){ripple(position.x,position.z);lastRipple=elapsed}}
player.position.copy(position);player.position.y=bob?Math.sin(elapsed*2.2)*.018:0;player.rotation.y=yaw;player.rotation.z=bob?Math.sin(elapsed*1.7)*.02:0;const cyaw=yaw+look;camera.position.set(position.x+Math.sin(yaw)*.47,1.38+(bob?Math.sin(elapsed*2.2)*.022:0),position.z+Math.cos(yaw)*.47);camera.rotation.set(pitch,cyaw,bob?Math.sin(elapsed*1.5)*.004:0);ducks.forEach((d,i)=>{let a=elapsed*.027+d.phase;d.obj.position.set(d.x+Math.cos(a)*9,.018*Math.sin(elapsed*2+i),d.z+Math.sin(a)*9);d.obj.rotation.y=-a;});for(const r of ripples){r.age+=dt;let s=.35+r.age*1.1;r.obj.scale.set(s,1,s);r.obj.material.opacity=Math.max(0,.2-r.age*.045)}motes.rotation.y=elapsed*.003;$('#pace').textContent=Math.abs(speed)>.35?'PADDLING':'FLOATING';let deg=((cyaw*180/Math.PI)%360+360)%360;$('#heading').textContent=['N','NW','W','SW','S','SE','E','NE'][Math.round(deg/45)%8];renderer.render(scene,camera)}animate();
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});
window.duckGame={getState:()=>({seed:worldSeed,islandCount:islands.length,position:{x:position.x,z:position.z},speed,playing,discovered:[...found].map(i=>places[i].name),sceneObjects:scene.children.length}),places};

if(document.modelContext?.registerTool){const lifecycle=new AbortController();for(const tool of [{name:'read_lake_state',description:'Read the duck position and discovered places.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>window.duckGame.getState()},{name:'set_auto_paddle',description:'Start or stop gentle forward paddling in the current direction.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'}},required:['enabled'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(typeof input?.enabled!=='boolean')throw new Error('enabled must be a boolean');if(input.enabled&&!playing)start();keys.auto=input.enabled;return {autoPaddle:!!keys.auto}}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}}addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
